// Sprachen: Deutsch ist die Quellsprache, T('deutscher Text') liefert die Übersetzung
const D = [["Bindematerial:", "Tying material:", "Materiale da costruzione:"],["Ein Euro-Nymphing-Abenteuer","A Euro nymphing adventure","Un'avventura di pesca a ninfa"],["Das Erbe der Smaragda","The Legacy of the Smaragda","L'eredità della Smaragda"],["Opas Rute. Opas Fliegendose. Fünf Strecken eines smaragdgrünen Flusses – und ein Fisch, den er nie landen konnte.","Grandpa's rod. Grandpa's fly box. Five beats of an emerald river – and one fish he never managed to land.","La canna del nonno. La sua scatola di mosche. Cinque tratti di un fiume color smeraldo – e un pesce che lui non riuscì mai a portare a guadino."],["Ans Wasser","To the water","All'acqua"],["Weiterfischen","Keep fishing","Continua a pescare"],["Neues Spiel","New game","Nuova partita"],["Neues Spiel beginnen? Der alte Spielstand geht verloren.","Start a new game? Your old save will be lost.","Iniziare una nuova partita? Il vecchio salvataggio andrà perso."],["lose","slack","lenta"],["Kontakt","contact","contatto"],["Zug","drag","tira"],["Schnurspannung","Line tension","Tensione della lenza"],["Kraft des Fisches","Fish's strength","Forza del pesce"],["↺ Strecke von vorn beginnen","↺ Restart this beat","↺ Ricomincia il tratto"],["waten","wade","guada"],["Stein","rock","sasso"],["ANHIEB","STRIKE","FERRA"],["DRILL","FIGHT","TIRA"],["Stufe {0}","Level {0}","Livello {0}"],["Stufe {0}!","Level {0}!","Livello {0}!"],["Neu:","New:","Novità:"],["✓ Alle Aufgaben hier erfüllt","✓ All tasks here complete","✓ Tutti gli obiettivi qui completati"],["Im tiefsten Teil des Gumpens bewegt sich ein großer Schatten …","In the deepest part of the pool, a large shadow is moving …","Nel punto più profondo della buca si muove una grande ombra …"],["Keine {0} mehr – öffne die Fliegendose.","No {0} left – open the fly box.","Niente più {0} – apri la scatola delle mosche."],["Dort ist kein Wasser.","There's no water there.","Lì non c'è acqua."],["Hänger! ANHIEB drücken, um die Nymphe zu lösen.","Snagged! Press STRIKE to free the nymph.","Incaglio! Premi FERRA per liberare la ninfa."],["Biss verpasst! Wenn der Sighter stoppt oder abtaucht: sofort ANHIEB.","Missed the take! When the sighter stops or dips: STRIKE at once.","Abboccata persa! Quando il sighter si ferma o affonda: FERRA subito."],["Da war etwas …","Something was there …","C'era qualcosa …"],["Die Nymphe kam nicht auf Tiefe. Schwerere Perle wählen oder weiter stromauf einwerfen.","The nymph didn't get down. Pick a heavier bead or cast further upstream.","La ninfa non è scesa in profondità. Scegli una pallina più pesante o lancia più a monte."],["Neue Fliege: {0}.","New fly: {0}.","Nuova mosca: {0}."],["In der Westentasche findest du noch zwei Pheasant Tails von Opa.","In your vest pocket you find two more of Grandpa's Pheasant Tails.","Nel taschino del gilet trovi ancora due Pheasant Tail del nonno."],["Binde dir neue in der Fliegendose.","Tie some new ones in the fly box.","Costruiscine di nuove nella scatola delle mosche."],["Zu viel lose Schnur – der Anhieb kam nicht durch.","Too much slack – the strike didn't come through.","Troppa lenza lenta – la ferrata non è arrivata."],["Abriss am Hänger – Fliege verloren.","Broke off on the snag – fly lost.","Rottura sull'incaglio – mosca persa."],["Hänger gelöst.","Snag freed.","Incaglio liberato."],["Nur ein Grundkontakt. Ticks sind kurz – ein Biss hält den Sighter fest.","Just a bottom tick. Ticks are brief – a take holds the sighter still.","Solo un tocco sul fondo. I tocchi sono brevi – una abboccata tiene fermo il sighter."],["Die Rute biegt sich bis ins Handteil. DAS IST ER!","The rod bends right down to the cork. IT'S HIM!","La canna si piega fino al sughero. È LUI!"],["Fisch hängt!","Fish on!","Pesce in canna!"],["Sie springt – Druck raus!","It jumps – ease off!","Salta – molla la pressione!"],["Kescher!","Net!","Guadino!"],["Im Sprung ausgehakt. Beim Sprung nicht gegenhalten!","Threw the hook in the jump. Don't pull against a jump!","Slamato nel salto. Non forzare durante il salto!"],["Ausgeschlitzt – zu wenig Spannung. Schonhaken verzeihen keine lose Schnur.","Hook pulled – not enough tension. Barbless hooks forgive no slack.","Slamato – troppa poca tensione. Gli ami senza ardiglione non perdonano la lenza lenta."],["Vorfach gerissen! Bei Fluchten den Druck rausnehmen.","Tippet snapped! Ease off the pressure on runs.","Finale rotto! Nelle fughe togli pressione."],["Sie schwimmt davon.","It swims away.","Nuota via."],["Zurück im Fluss.","Back in the river.","Di nuovo nel fiume."],["Petri Heil!","Tight lines!","In bocca al lupo!"],["Ein Schwanzschlag – weg ist sie.","A flick of the tail – and it's gone.","Un colpo di coda – ed è sparita."],["Hier endet die Strecke. Oben kannst du sie von vorn beginnen.","The beat ends here. Use the button above to start it over.","Il tratto finisce qui. In alto puoi ricominciarlo da capo."],["Weiter unten ist die Brücke. Fisch stromauf!","The bridge is further down. Fish upstream!","Più giù c'è il ponte. Pesca verso monte!"],["Zu tief zum Waten.","Too deep to wade.","Troppo profondo per guadare."],["Weiter weg vom Wasser kommst du nicht an die Fische.","Any further from the water and you can't reach the fish.","Più lontano dall'acqua non arrivi ai pesci."],["Da liegt ein Fels im Weg.","There's a boulder in the way.","C'è un masso in mezzo."],["Fisch vergrämt! Langsam waten und Abstand zu den Standplätzen halten.","Fish spooked! Wade slowly and keep your distance from the lies.","Pesce spaventato! Guada piano e tieniti lontano dalle tane."],["Zurück am Einstieg. Die Fische stehen neu.","Back at the start. The fish have moved to new lies.","Di nuovo all'inizio. I pesci si sono ridistribuiti."],["Finger aufs Wasser legen, Zielring stromauf schieben, loslassen = Wurf. Fische stehen vor, neben und hinter Steinen, in Gumpen und tiefen Rinnen.","Put a finger on the water, slide the target ring upstream, release = cast. Fish hold in front of, beside and behind rocks, in pools and deep runs.","Appoggia il dito sull'acqua, sposta l'anello di mira a monte, rilascia = lancio. I pesci stanno davanti, di fianco e dietro ai sassi, nelle buche e nelle correntine profonde."],["Neuer Wurf: Zielring setzen und loslassen. Mit dem Stick unten links watest du frei durch den Fluss – langsam, sonst flüchten die Fische.","Next cast: place the target ring and release. Use the stick at the bottom left to wade freely – slowly, or the fish will bolt.","Nuovo lancio: posiziona l'anello di mira e rilascia. Con lo stick in basso a sinistra guadi liberamente nel fiume – piano, altrimenti i pesci scappano."],["Der Sighter stoppt – nach oben wischen oder ANHIEB drücken!","The sighter stops – swipe up or press STRIKE!","Il sighter si ferma – scorri verso l'alto o premi FERRA!"],["Finger nach unten ziehen und die Rute mit der Drift führen. Ring am Sighter grün = Kontakt, blau = zu lose, rot = du ziehst.","Drag your finger down and lead the rod with the drift. Ring at the sighter green = contact, blue = too slack, red = you are dragging.","Trascina il dito verso il basso e accompagna la passata con la canna. Anello sul sighter verde = contatto, blu = troppo lenta, rosso = stai tirando."],["Finger nach unten ziehen = Druck, je weiter desto mehr. Bei Fluchten nachgeben, nie ganz locker lassen. Seitlich ziehen = Seitendruck.","Drag down = pressure, the further the more. Give on runs, never go fully slack. Drag sideways = side pressure.","Trascina verso il basso = pressione, più vai più aumenta. Cedi nelle fughe, mai mollare del tutto. Trascina di lato = pressione laterale."],["Der Alte vom Smaragdgumpen","The Old One of the Emerald Pool","Il Vecchio della Buca di Smeraldo"],["Neue Art im Fangbuch!","New species in the catch log!","Nuova specie nel registro!"],["Neuer persönlicher Rekord!","New personal best!","Nuovo record personale!"],["Gefangen","Caught","Catturato"],["Bindematerial","tying material","materiale da costruzione"],["Aufgabe erfüllt:","Task complete:","Obiettivo completato:"],["Zurücksetzen","Release","Rilascia"],["Gumpen","pool","buca"],["Tasche","pocket","tasca dietro il sasso"],["Kissen","cushion","cuscino davanti al sasso"],["Kante","seam","filo di corrente"],["Rinne","run","correntina"],["Stein umgedreht","Rock turned over","Sasso rivoltato"],["Du hebst einen faustgroßen Stein aus der Strömung und drehst ihn um.","You lift a fist-sized rock out of the current and turn it over.","Sollevi dalla corrente un sasso grande come un pugno e lo rivolti."],["Massenhaft {0}","Masses of {0}","{0} in abbondanza"],["Vereinzelt {0}","A few {0}","Qualche esemplare: {0}"],["Passende Muster:","Matching patterns:","Imitazioni adatte:"],["Wasser:","Water:","Acqua:"],["Bei angetrübtem Wasser dürfen Fliegen auffälliger sein (Hotspot).","In coloured water flies can be flashier (hotspot).","Con acqua velata le mosche possono essere più vistose (hotspot)."],["Bei klarem Wasser lieber natürlich und fein fischen.","In clear water fish natural and fine.","Con acqua limpida meglio pescare naturale e sottile."],["Stein zurücklegen","Put the rock back","Rimetti a posto il sasso"],["Neues Revier freigeschaltet:","New beat unlocked:","Nuovo tratto sbloccato:"],["Zum Revier wandern","Hike to the beat","Raggiungi il tratto"],["Hier weiterfischen","Keep fishing here","Continua a pescare qui"],["Schließen","Close","Chiudi"],["Tagebuch","Diary","Diario"],["Reviere & Aufgaben","Beats & tasks","Tratti e obiettivi"],["Opas Seiten","Grandpa's pages","Le pagine del nonno"],["Du bist hier","You are here","Sei qui"],["Hier fischen","Fish here","Pesca qui"],["Erfülle alle Aufgaben in „{0}\".","Complete all tasks in “{0}”.","Completa tutti gli obiettivi in «{0}»."],["Fliegendose","Fly box","Scatola delle mosche"],["eine Fliege binden kostet 2","tying a fly costs 2","costruire una mosca costa 2"],["ab Stufe {0}","from level {0}","dal livello {0}"],["Imitiert:","Imitates:","Imita:"],["Angeknotet","Tied on","Legata"],["Anknoten","Tie on","Lega"],["Binden (−2)","Tie (−2)","Costruisci (−2)"],["Tungstenperle","Tungsten bead","Pallina in tungsteno"],["Schwerer = schneller am Grund, aber mehr Hänger. Faustregel: so leicht wie möglich, so schwer wie nötig.","Heavier = on the bottom faster, but more snags. Rule of thumb: as light as possible, as heavy as necessary.","Più pesante = più veloce sul fondo, ma più incagli. Regola: più leggera possibile, pesante quanto serve."],["Vorfachspitze","Tippet","Finale"],["Dünner = mehr Bisse und schnelleres Absinken, reißt aber früher.","Thinner = more takes and faster sinking, but breaks sooner.","Più sottile = più abboccate e affondamento più rapido, ma si rompe prima."],["Zurück ans Wasser","Back to the water","Torna all'acqua"],["Fangbuch","Catch log","Registro catture"],["Gesamt:","Total:","Totale:"],["Fische gefangen und zurückgesetzt","fish caught and released","pesci catturati e rilasciati"],["noch nicht gefangen","not caught yet","non ancora catturato"],["gefangen","caught","catturato"],["Einstellungen","Settings","Impostazioni"],["Bisshilfe","Take indicator","Aiuto abboccata"],["Lupe leuchtet und Handy vibriert beim Biss. Ohne Hilfe: +25 % XP.","The magnifier glows and the phone vibrates on a take. Without it: +25 % XP.","La lente si illumina e il telefono vibra all'abboccata. Senza aiuto: +25 % XP."],["Führungshilfe","Lead assist","Aiuto guida"],["Die Rute folgt der Drift ein Stück von selbst; in schnellem Wasser musst du nachhelfen. Ohne: +15 % XP.","The rod follows the drift partly by itself; in fast water you have to help. Without it: +15 % XP.","La canna segue la passata in parte da sola; in acqua veloce devi aiutarla. Senza: +15 % XP."],["Klare Sicht","Clear view","Vista limpida"],["Blendet die Spiegelung auf dem Wasser aus, damit du die Fische besser siehst. Ohne: +35 XP pro Fisch.","Hides the reflection on the water so you can see the fish better. Without it: +35 XP per fish.","Nasconde il riflesso sull'acqua per vedere meglio i pesci. Senza: +35 XP per pesce."],["Hohe Grafikqualität","High graphics quality","Grafica di alta qualità"],["Schatten, Gras und volle Auflösung. Ausschalten, wenn es ruckelt.","Shadows, grass and full resolution. Turn off if it stutters.","Ombre, erba e risoluzione piena. Disattiva se va a scatti."],["Vibration","Vibration","Vibrazione"],["Haptik bei Biss und Drill (nur am Handy).","Haptics on takes and during the fight (phone only).","Vibrazione all'abboccata e nel combattimento (solo telefono)."],["Ton","Sound","Audio"],["Flussrauschen und Effekte.","River noise and effects.","Rumore del fiume ed effetti."],["Sprache","Language","Lingua"],["Steuerung","Controls","Comandi"],["<b>Handy:</b> Finger aufs Wasser, Zielring schieben, loslassen = Wurf · nach unten ziehen = Rute führen · nach oben wischen (oder ANHIEB) = anschlagen · im Drill nach unten ziehen = Druck, seitlich = Seitendruck · Stick unten links = waten · am Himmel oder Ufer ziehen = umschauen.","<b>Phone:</b> finger on the water, slide the target ring, release = cast · drag down = lead the rod · swipe up (or STRIKE) = set the hook · in the fight drag down = pressure, sideways = side pressure · stick at the bottom left = wade · drag on the sky or bank = look around.","<b>Telefono:</b> dito sull'acqua, sposta l'anello di mira, rilascia = lancio · trascina in basso = guida la canna · scorri in alto (o FERRA) = ferrata · nel combattimento trascina in basso = pressione, di lato = pressione laterale · stick in basso a sinistra = guada · trascina sul cielo o sulla riva = guardati intorno."],["<b>PC:</b> wie am Handy mit gedrückter Maustaste · Leertaste / Rechtsklick = Anhieb, im Drill halten = Druck · W/A/S/D = waten, im Drill A/D = Seitendruck · Rechtsklick ziehen oder Q/E = umschauen · F = Fliegendose · T = Tagebuch.","<b>PC:</b> as on the phone with the mouse button held · Space / right click = strike, hold in the fight = pressure · W/A/S/D = wade, in the fight A/D = side pressure · right-drag or Q/E = look around · F = fly box · T = diary.","<b>PC:</b> come sul telefono tenendo premuto il mouse · Spazio / clic destro = ferrata, nel combattimento tieni premuto = pressione · W/A/S/D = guada, nel combattimento A/D = pressione laterale · trascina col destro o Q/E = guardati intorno · F = scatola delle mosche · T = diario."],["Spielstand löschen","Delete save","Cancella salvataggio"],["Wirklich den gesamten Spielstand löschen?","Really delete the entire save?","Cancellare davvero tutto il salvataggio?"],["Bachforelle","Brown trout","Trota fario"],["Regenbogenforelle","Rainbow trout","Trota iridea"],["Äsche","Grayling","Temolo"],["Bachsaibling","Brook trout","Salmerino di fonte"],["Barbe","Barbel","Barbo"],["Marmorata","Marble trout","Trota marmorata"],["Steht gern in Taschen hinter Steinen und unter überhängenden Ufern.","Likes to hold in pockets behind rocks and under overhanging banks.","Ama stare nelle tasche dietro i sassi e sotto le rive sporgenti."],["Liebt schnelles, sauerstoffreiches Wasser – und springt im Drill.","Loves fast, oxygen-rich water – and jumps in the fight.","Ama l'acqua veloce e ossigenata – e salta durante il combattimento."],["Die Fahnenträgerin. Steht in gleichmäßigen Zügen über Kies, nimmt zart.","The lady with the banner fin. Holds in even glides over gravel, takes gently.","La dama dalla pinna a bandiera. Sta nelle lame regolari sopra la ghiaia, abbocca con delicatezza."],["Kaltes, schattiges Wasser. Weiß gesäumte Flossen verraten ihn.","Cold, shaded water. White-edged fins give it away.","Acqua fredda e ombrosa. Le pinne orlate di bianco lo tradiscono."],["Klebt am Grund. Wer sie hakt, braucht Geduld und ein gutes Vorfach.","Hugs the bottom. Hook one and you need patience and a good tippet.","Sta incollato al fondo. Chi lo allama ha bisogno di pazienza e di un buon finale."],["Die Marmorierte. Königin der smaragdgrünen Flüsse.","The marbled one. Queen of the emerald rivers.","La marmorata. Regina dei fiumi color smeraldo."],["Eintagsfliegenlarven","mayfly nymphs","ninfe di effimera"],["schlank, olivbraun, drei Schwanzfäden","slim, olive-brown, three tails","snelle, bruno-oliva, tre cerci"],["Köcherfliegenlarven","caddis larvae","larve di tricottero"],["im Köcher aus Steinchen, grüner Kopf schaut heraus","in a case of tiny stones, green head peeking out","in un astuccio di sassolini, spunta la testa verde"],["Steinfliegenlarven","stonefly nymphs","ninfe di plecottero"],["groß, flach, zwei Schwanzfäden","large, flat, two tails","grandi, piatte, due cerci"],["Bachflohkrebse","freshwater shrimps","gamberetti d'acqua dolce"],["grau-oliv, gekrümmt, wuseln seitlich davon","grey-olive, curved, scuttling off sideways","grigio-oliva, ricurvi, scappano di lato"],["Würmer","worms","vermi"],["vom Regen ausgespült","washed out by the rain","dilavati dalla pioggia"],["Steinfliegennymphe","Stonefly Nymph","Ninfa di plecottero"],["Fasanenschwanz, Kupferdraht. Der Klassiker – imitiert fast jede Eintagsfliegenlarve.","Pheasant tail, copper wire. The classic – imitates almost any mayfly nymph.","Coda di fagiano, filo di rame. Il classico – imita quasi ogni ninfa di effimera."],["Glatt lackiert, kein Widerstand. Sinkt wie ein Stein – ideal für schnelles Wasser.","Smooth and varnished, no resistance. Sinks like a stone – ideal for fast water.","Liscia e verniciata, nessuna resistenza. Affonda come un sasso – ideale per acqua veloce."],["Nur Hasenohr-Dubbing. Unscheinbar, struppig – und für Bachflohkrebs-Fresser unwiderstehlich.","Just hare's ear dubbing. Plain, scruffy – and irresistible to shrimp eaters.","Solo dubbing di orecchio di lepre. Anonima, arruffata – e irresistibile per chi mangia gamberetti."],["Pheasant Tail mit pinkem Hotspot. Fällt auf, wenn das Wasser Farbe hat.","Pheasant Tail with a pink hotspot. Stands out when the water has colour.","Pheasant Tail con hotspot rosa. Si fa notare quando l'acqua è velata."],["Köcher aus Hasenhaar, chartreuse Kopf. Wenn die Fische Köcher samt Larve fressen.","Case of hare's fur, chartreuse head. For when fish eat the case with the larva.","Astuccio in pelo di lepre, testa chartreuse. Quando i pesci mangiano l'astuccio con tutta la larva."],["Gummiwurm in Pink. Puristen rümpfen die Nase – bei trübem Wasser fängt er trotzdem.","Rubber worm in pink. Purists turn up their noses – in dirty water it catches anyway.","Verme di gomma rosa. I puristi storcono il naso – con acqua torbida cattura lo stesso."],["Groß, dunkel, mit Gummibeinchen. Ein Happen, für den auch die Großen aufstehen.","Big, dark, with rubber legs. A mouthful even the big ones move for.","Grande, scura, con zampette di gomma. Un boccone per cui si muovono anche i grossi."],["Pfauengras und roter Schwanz. Äschen können nicht widerstehen.","Peacock herl and a red tail. Grayling can't resist.","Herl di pavone e coda rossa. I temoli non resistono."],["Frenchie & Polbrille – du siehst Fische jetzt deutlicher im Wasser","Frenchie & polarised glasses – you now see fish more clearly in the water","Frenchie e occhiali polarizzati – ora vedi meglio i pesci nell'acqua"],["Peeping Caddis & 0,12er Fluorocarbon","Peeping Caddis & 0.12 mm fluorocarbon","Peeping Caddis e fluorocarbon 0,12"],["Red Tag Jig & 0,10er Fluorocarbon","Red Tag Jig & 0.10 mm fluorocarbon","Red Tag Jig e fluorocarbon 0,10"],["glasklar","crystal clear","cristallina"],["leicht angetrübt","slightly coloured","leggermente velata"],["trüb","murky","torbida"],["Morgennebel","morning mist","nebbia mattutina"],["Mittagssonne","midday sun","sole di mezzogiorno"],["Abendlicht","evening light","luce della sera"],["bedeckt","overcast","coperto"],["Die Wiesenstrecke","The Meadow Beat","Il tratto dei prati"],["Wo alles begann","Where it all began","Dove tutto ebbe inizio"],["Die Rausche","The Riffles","Le rapide"],["Taschenwasser","Pocket water","Acqua a tasche"],["Der Äschenzug","The Grayling Glide","La lama dei temoli"],["Feines Zeug","Fine tackle","Roba sottile"],["Die Klamm","The Gorge","La forra"],["Tief und schnell","Deep and fast","Profonda e veloce"],["Der Smaragdgumpen","The Emerald Pool","La buca di smeraldo"],["Das Reich des Alten","The realm of the Old One","Il regno del Vecchio"],["Fange deinen ersten Fisch","Catch your first fish","Cattura il tuo primo pesce"],["Fange 4 Fische in der Wiesenstrecke","Catch 4 fish in the Meadow Beat","Cattura 4 pesci nel tratto dei prati"],["Drehe einen Stein um und fange einen Fisch auf die passende Nymphe","Turn over a rock and catch a fish on the matching nymph","Rivolta un sasso e cattura un pesce con la ninfa giusta"],["Fange 4 Fische an Steinen – davor, daneben oder dahinter","Catch 4 fish at rocks – in front, beside or behind","Cattura 4 pesci vicino ai sassi – davanti, di fianco o dietro"],["Fange eine Regenbogenforelle ab 36 cm","Catch a rainbow trout of 36 cm or more","Cattura una trota iridea di almeno 36 cm"],["Fange einen Fisch mit 3,5-mm-Perle oder schwerer","Catch a fish on a 3.5 mm bead or heavier","Cattura un pesce con pallina da 3,5 mm o più pesante"],["Fange 3 Äschen","Catch 3 grayling","Cattura 3 temoli"],["Fange eine Äsche ab 40 cm","Catch a grayling of 40 cm or more","Cattura un temolo di almeno 40 cm"],["Fange einen Fisch am 0,12er Vorfach oder feiner","Catch a fish on 0.12 mm tippet or finer","Cattura un pesce con finale 0,12 o più sottile"],["Fange 5 Fische in der Klamm","Catch 5 fish in the Gorge","Cattura 5 pesci nella forra"],["Fange einen Bachsaibling","Catch a brook trout","Cattura un salmerino di fonte"],["Fange einen Fisch ab 48 cm","Catch a fish of 48 cm or more","Cattura un pesce di almeno 48 cm"],["Fange eine Marmorata","Catch a marble trout","Cattura una trota marmorata"],["Fange 3 Fische ab 42 cm","Catch 3 fish of 42 cm or more","Cattura 3 pesci di almeno 42 cm"],["Lande den Alten – und lass ihn wieder schwimmen","Land the Old One – and let him swim again","Porta a guadino il Vecchio – e lascialo tornare a nuotare"],["Die Fliegendose","The Fly Box","La scatola delle mosche"],["Opas Tagebuch · erste Seite","Grandpa's diary · first page","Diario del nonno · prima pagina"],["Opa Emil ist im Winter gegangen. Dir hat er drei Dinge hinterlassen: eine zehn Fuß lange Nymphenrute der Klasse 3, eine zerkratzte Fliegendose – und dieses Tagebuch.","Grandpa Emil passed away in the winter. He left you three things: a ten-foot 3-weight nymphing rod, a scratched fly box – and this diary.","Nonno Emil se n'è andato in inverno. Ti ha lasciato tre cose: una canna da ninfa di dieci piedi coda 3, una scatola di mosche graffiata – e questo diario."],["„Mein Lieber\", steht auf der ersten Seite, „die Smaragda hat mir mehr beigebracht als jeder Mensch. Ich habe ihre fünf schönsten Strecken für dich aufgeschrieben. Fisch sie der Reihe nach. Am Ende wartet einer, den ich nie landen konnte.\"","“My dear,” it says on the first page, “the Smaragda taught me more than any person ever did. I have written down her five finest beats for you. Fish them in order. At the end waits one I never managed to land.”","«Caro mio», c'è scritto sulla prima pagina, «la Smaragda mi ha insegnato più di qualunque persona. Ho annotato per te i suoi cinque tratti più belli. Pescali in ordine. Alla fine ne aspetta uno che non sono mai riuscito a portare a guadino.»"],["„Fang in der Wiesenstrecke an. Kurze Schnur, hohe Rute, und lass die Nymphe so treiben, als hinge sie an gar nichts. Der Sighter sagt dir alles – du musst ihm nur zuhören.\"","“Start in the Meadow Beat. Short line, high rod, and let the nymph drift as if it were tied to nothing at all. The sighter tells you everything – you only have to listen.”","«Comincia dal tratto dei prati. Lenza corta, canna alta, e lascia scendere la ninfa come se non fosse legata a niente. Il sighter ti dice tutto – devi solo ascoltarlo.»"],["Opas Tagebuch · zweite Seite","Grandpa's diary · second page","Diario del nonno · seconda pagina"],["„Die Rausche sieht aus wie Chaos. Ist sie nicht. Hinter jedem Stein liegt eine Tasche ruhiges Wasser, und in jeder Tasche wohnt ein Fisch, der nur auf den Aufzug mit Futter wartet.\"","“The Riffles look like chaos. They aren't. Behind every rock lies a pocket of calm water, and in every pocket lives a fish just waiting for the food conveyor.”","«Le rapide sembrano un caos. Non lo sono. Dietro ogni sasso c'è una tasca di acqua calma, e in ogni tasca abita un pesce che aspetta solo che la corrente gli porti da mangiare.»"],["„Hier brauchst du Gewicht. Die Nymphe hat einen halben Meter Zeit, um unten anzukommen. Nimm die schwerere Perle, wirf knapp über den Stein und halte Kontakt – die Bisse kommen schnell und hart.\"","“Here you need weight. The nymph has half a metre to get down. Take the heavier bead, cast just above the rock and keep contact – the takes come fast and hard.”","«Qui serve peso. La ninfa ha mezzo metro per arrivare giù. Prendi la pallina più pesante, lancia appena sopra il sasso e tieni il contatto – le abboccate arrivano rapide e decise.»"],["„Und wate von unten nach oben. Wer von oben kommt, dem laufen die Forellen davon, bevor er den ersten Wurf gemacht hat.\"","“And wade from the bottom up. Come from above and the trout are gone before you have made your first cast.”","«E guada da valle verso monte. Chi arriva da monte vede scappare le trote prima ancora del primo lancio.»"],["Die Fahnenträgerinnen","The Ladies of the Stream","Le dame del fiume"],["Opas Tagebuch · dritte Seite","Grandpa's diary · third page","Diario del nonno · terza pagina"],["„Im Zug unterhalb der Brücke stehen die Äschen. Deine Großmutter nannte sie die Damen des Flusses, weil sie sich nichts aufdrängen lassen.\"","“In the glide below the bridge hold the grayling. Your grandmother called them the ladies of the river, because nothing can be forced on them.”","«Nella lama sotto il ponte stanno i temoli. Tua nonna li chiamava le dame del fiume, perché non si lasciano imporre nulla.»"],["„Äschen sehen alles. Ein dickes Vorfach, eine Nymphe, die auch nur einen Hauch zu schnell treibt – und sie drehen ab. Fisch fein, fisch leicht, und schau genau hin: Ihr Biss ist oft nur ein Zögern im Sighter.\"","“Grayling see everything. A thick tippet, a nymph drifting just a touch too fast – and they turn away. Fish fine, fish light, and look closely: their take is often no more than a hesitation in the sighter.”","«I temoli vedono tutto. Un finale grosso, una ninfa che scende appena un filo troppo veloce – e girano via. Pesca sottile, pesca leggero, e guarda bene: la loro abboccata spesso è solo un'esitazione del sighter.»"],["„Dreh vorher einen Stein um. Was darunter krabbelt, gehört ans Vorfach.\"","“Turn over a rock first. Whatever crawls underneath belongs on your tippet.”","«Prima rivolta un sasso. Quello che ci cammina sotto va legato al finale.»"],["Opas Tagebuch · vierte Seite","Grandpa's diary · fourth page","Diario del nonno · quarta pagina"],["„In der Klamm ist es auch im August kalt. Das Wasser ist tief, schnell und dunkel, und die Fische sind es auch.\"","“In the Gorge it is cold even in August. The water is deep, fast and dark, and so are the fish.”","«Nella forra fa freddo anche ad agosto. L'acqua è profonda, veloce e scura, e lo sono anche i pesci.»"],["„Vier Millimeter Tungsten sind hier keine Schande. Wirf weit stromauf, gib der Nymphe Zeit zum Sinken, und rechne mit Hängern – wer nie hängt, fischt zu hoch.\"","“Four millimetres of tungsten are no shame here. Cast well upstream, give the nymph time to sink, and expect snags – whoever never snags is fishing too high.”","«Quattro millimetri di tungsteno qui non sono una vergogna. Lancia bene a monte, dai alla ninfa il tempo di affondare e metti in conto gli incagli – chi non incaglia mai pesca troppo alto.»"],["„Hier habe ich zum ersten Mal eine Marmorierte gesehen. Sie stieg aus dem Grünen auf wie ein Gespenst und war wieder weg. Da wusste ich, dass weiter oben noch Größere stehen.\"","“This is where I first saw a marble trout. It rose out of the green like a ghost and was gone again. Then I knew that bigger ones were holding further up.”","«Qui ho visto per la prima volta una marmorata. È salita dal verde come un fantasma ed è sparita di nuovo. Allora ho capito che più su ce ne sono di più grandi.»"],["Der Alte","The Old One","Il Vecchio"],["Opas Tagebuch · letzte Seite","Grandpa's diary · last page","Diario del nonno · ultima pagina"],["„Der Smaragdgumpen. Hier endet meine Karte.\"","“The Emerald Pool. This is where my map ends.”","«La buca di smeraldo. Qui finisce la mia mappa.»"],["„Dreimal hatte ich ihn am Haken. Einmal hat er mir das Vorfach gesprengt, einmal den Haken aufgebogen, und beim dritten Mal ist er einfach stehen geblieben, bis ich nachgegeben habe. Eine Marmorata, lang wie mein Arm. Ich nenne ihn den Alten.\"","“Three times I had him on. Once he snapped my tippet, once he straightened the hook, and the third time he simply stood still until I gave in. A marble trout as long as my arm. I call him the Old One.”","«Tre volte l'ho avuto all'amo. Una volta mi ha spaccato il finale, una volta ha aperto l'amo, e la terza è semplicemente rimasto fermo finché non ho ceduto io. Una marmorata lunga come il mio braccio. Lo chiamo il Vecchio.»"],["„Er zeigt sich nicht jedem. Beweise dem Gumpen erst, dass du fischen kannst. Dann steht er am tiefsten Punkt, dicht am Grund, und nimmt nur, was schwer genug ist, um zu ihm hinunterzukommen, und was aussieht wie echtes Futter.\"","“He does not show himself to everyone. First prove to the pool that you can fish. Then he holds at the deepest point, tight to the bottom, and takes only what is heavy enough to get down to him and looks like real food.”","«Non si mostra a chiunque. Dimostra prima alla buca che sai pescare. Allora starà nel punto più profondo, attaccato al fondo, e prenderà solo ciò che è abbastanza pesante da arrivare fino a lui e che sembra cibo vero.»"],["„Wenn du ihn hast: Halt ihn kurz ins Wasser, schau ihn dir an – und lass ihn gehen. Er gehört dem Fluss.\"","“When you have him: hold him in the water for a moment, take a good look – and let him go. He belongs to the river.”","«Quando ce l'hai: tienilo un attimo in acqua, guardalo bene – e lascialo andare. Appartiene al fiume.»"],["Zurück in den Fluss","Back into the River","Di nuovo nel fiume"],["Deine Handschrift","Your handwriting","La tua calligrafia"],["Zweiundneunzig Zentimeter. Du hältst ihn im Kescher, die marmorierte Flanke leuchtet im grünen Wasser, und für einen Augenblick ist es ganz still.","Ninety-two centimetres. You hold him in the net, the marbled flank glows in the green water, and for a moment everything is still.","Novantadue centimetri. Lo tieni nel guadino, il fianco marmorizzato brilla nell'acqua verde, e per un istante tutto tace."],["Dann senkst du den Kescherrand. Der Alte bleibt noch einen Herzschlag lang stehen, als wolle er sich dein Gesicht merken, und gleitet zurück in die Tiefe.","Then you lower the rim of the net. The Old One stays for one more heartbeat, as if to remember your face, and glides back into the deep.","Poi abbassi il bordo del guadino. Il Vecchio resta fermo ancora per un battito, come per ricordare il tuo viso, e scivola di nuovo nel profondo."],["Am Abend schreibst du unter Opas letzte Zeile: „Ich habe ihn gelandet, Opa. Und er schwimmt wieder.\" Die Smaragda gehört jetzt dir – jede Strecke, jede Tasche, jeder Fisch, der noch größer werden will.","In the evening you write beneath Grandpa's last line: “I landed him, Grandpa. And he is swimming again.” The Smaragda is yours now – every beat, every pocket, every fish that still wants to grow.","La sera scrivi sotto l'ultima riga del nonno: «L'ho portato a guadino, nonno. E nuota di nuovo.» La Smaragda adesso è tua – ogni tratto, ogni tasca, ogni pesce che vuole ancora crescere."],["Staffel 1 · Opas Tagebuch", "Season 1 · Grandpa's diary", "Stagione 1 · Il diario del nonno"],["Staffel 2 · Lenis Karte", "Season 2 · Leni's map", "Stagione 2 · La mappa di Leni"],["Staffel 3 · Herbst im Unterlauf", "Season 3 · Autumn on the lower river", "Stagione 3 · Autunno nel basso corso"],["Staffel 4 · Der Winterkönig", "Season 4 · The winter king", "Stagione 4 · Il re d'inverno"],["Neue Staffel freigeschaltet:", "New season unlocked:", "Nuova stagione sbloccata:"],["Staffel beginnen", "Start the season", "Inizia la stagione"],["Seeforelle", "Lake trout", "Trota lacustre"],["Silbern und schwer. Zieht im Herbst aus dem See in den Auslauf und prüft jede Nymphe zweimal.", "Silver and heavy. Runs out of the lake into the outflow in autumn and inspects every nymph twice.", "Argentea e pesante. In autunno risale dal lago nell'emissario e controlla ogni ninfa due volte."],["Huchen", "Huchen", "Huchen"],["Der Donaulachs. Kupferrot, einzelgängerisch, frisst Forellen – und nimmt nur einen großen Happen tief am Grund.", "The Danube salmon. Copper red, a loner, eats trout – and only takes a big mouthful deep on the bottom.", "Il salmone del Danubio. Rosso rame, solitario, mangia trote – e prende solo un boccone grosso, giù sul fondo."],["Ein Stück Wischmopp am Haken. Sieht albern aus, treibt wie eine fette Larve – und fängt, wenn nichts anderes geht.", "A scrap of mop on a hook. Looks silly, drifts like a fat grub – and catches when nothing else will.", "Un pezzo di mocio su un amo. Sembra ridicola, deriva come una larva grassa – e prende quando nient'altro funziona."],["Ein leuchtendes Fischei aus Chenille. Im kalten Wasser fressen Forellen den Laich der anderen.", "A glowing fish egg made of chenille. In cold water trout eat the spawn of others.", "Un uovo di pesce luminoso in ciniglia. Nell'acqua fredda le trote mangiano le uova delle altre."],["Schwer, dunkel, lang wie ein Finger. Kein Imitat für Zaghafte – gebaut für den Kolk und das, was darin jagt.", "Heavy, dark, long as a finger. Not a pattern for the timid – built for the deep hole and what hunts in it.", "Pesante, scura, lunga come un dito. Non è per i timidi – costruita per la buca profonda e per ciò che vi caccia."],["Mop Fly", "Mop Fly", "Mop Fly"],["0,18er Vorfach – für die ganz Großen", "0.18 tippet – for the really big ones", "Finale dello 0,18 – per i più grossi"],["Eggstasy", "Eggstasy", "Eggstasy"],["Huchen-Jig", "Huchen jig", "Jig da huchen"],["Fange 4 Bachsaiblinge", "Catch 4 brook trout", "Cattura 4 salmerini di fonte"],["Fange 3 Fische mit der leichten 2,5-mm-Perle", "Catch 3 fish on the light 2.5 mm bead", "Cattura 3 pesci con la pallina leggera da 2,5 mm"],["Fange 3 Fische in Gumpen", "Catch 3 fish in pools", "Cattura 3 pesci nelle buche"],["Der Quellbach", "The headwater brook", "Il ruscello sorgivo"],["Klein und kalt", "Small and cold", "Piccolo e freddo"],["Fange eine Seeforelle", "Catch a lake trout", "Cattura una trota lacustre"],["Fange eine Seeforelle ab 60 cm", "Catch a lake trout of 60 cm or more", "Cattura una trota lacustre di almeno 60 cm"],["Fange 6 Fische auf die passende Nymphe (vorher Stein umdrehen)", "Catch 6 fish on the matching nymph (turn a rock first)", "Cattura 6 pesci con la ninfa giusta (prima gira un sasso)"],["Der Seeauslauf", "The lake outflow", "L'emissario del lago"],["Wo die Großen ziehen", "Where the big ones run", "Dove passano i grossi"],["Fange 4 Barben", "Catch 4 barbel", "Cattura 4 barbi"],["Fange 4 Fische bei angetrübtem oder trübem Wasser", "Catch 4 fish in coloured or murky water", "Cattura 4 pesci con acqua velata o torbida"],["Fange eine Barbe ab 60 cm", "Catch a barbel of 60 cm or more", "Cattura un barbo di almeno 60 cm"],["Der Auwald", "The floodplain forest", "Il bosco golenale"],["Trübes Wasser, graue Schatten", "Coloured water, grey shadows", "Acqua velata, ombre grigie"],["Fange 5 Fische auf eine Reizfliege (Frenchie, Squirmy, Red Tag, Mop Fly)", "Catch 5 fish on an attractor fly (Frenchie, Squirmy, Red Tag, Mop Fly)", "Cattura 5 pesci con una mosca di richiamo (Frenchie, Squirmy, Red Tag, Mop Fly)"],["Fange eine Regenbogenforelle ab 52 cm", "Catch a rainbow trout of 52 cm or more", "Cattura una trota iridea di almeno 52 cm"],["Fange 3 Fische ab 50 cm", "Catch 3 fish of 50 cm or more", "Cattura 3 pesci di almeno 50 cm"],["Das alte Wehr", "The old weir", "La vecchia briglia"],["Weißes Wasser", "White water", "Acqua bianca"],["Fange 5 Äschen", "Catch 5 grayling", "Cattura 5 temoli"],["Fange eine Äsche ab 46 cm", "Catch a grayling of 46 cm or more", "Cattura un temolo di almeno 46 cm"],["Fange 3 Fische am 0,10er Vorfach", "Catch 3 fish on 0.10 tippet", "Cattura 3 pesci con il finale dello 0,10"],["Der Winterzug", "The winter run", "La corrente d'inverno"],["Raureif und feines Zeug", "Hoarfrost and fine gear", "Brina e fili sottili"],["Fange einen Huchen", "Catch a huchen", "Cattura un huchen"],["Fange 3 Fische ab 55 cm", "Catch 3 fish of 55 cm or more", "Cattura 3 pesci di almeno 55 cm"],["Lande einen Huchen ab 100 cm – und lass ihn wieder schwimmen", "Land a huchen of 100 cm or more – and let it swim again", "Porta a guadino un huchen di almeno 100 cm – e lascialo nuotare di nuovo"],["Die Mündung", "The confluence", "La confluenza"],["Wo der Huchen jagt", "Where the huchen hunts", "Dove caccia l'huchen"],["Lenis Karte", "Leni's map", "La mappa di Leni"],["Omas Karte · Staffel 2", "Grandma's map · season 2", "La mappa della nonna · stagione 2"],["Hinten im Tagebuch klebt ein gefaltetes Blatt, das du bisher übersehen hast. Eine Karte, mit Bleistift gezeichnet, in einer anderen Handschrift: Oma Leni.", "At the back of the diary there is a folded sheet you had overlooked. A map, drawn in pencil, in a different hand: Grandma Leni.", "In fondo al diario c'è un foglio piegato che non avevi notato. Una mappa disegnata a matita, in un'altra calligrafia: nonna Leni."],["„Emil glaubt, der Fluss fängt an der Wiese an\", steht am Rand. „Dabei kommen seine Fische von viel weiter oben. Geh zum Quellbach. Dort ist alles klein – das Wasser, die Saiblinge, und deine Fehler dürfen es auch sein.\"", "\"Emil thinks the river starts at the meadow,\" it says in the margin. \"But his fish come from much further up. Go to the headwater brook. Everything is small there – the water, the brook trout, and your mistakes may be small too.\"", "«Emil crede che il fiume cominci al prato», c'è scritto a margine. «Ma i suoi pesci vengono da molto più su. Vai al ruscello sorgivo. Lì tutto è piccolo – l'acqua, i salmerini, e anche i tuoi errori possono esserlo.»"],["„Nimm die leichteste Perle, die du hast. Im Quellbach plumpst man nicht, man legt ab.\"", "\"Take the lightest bead you have. In the brook you don't plop, you place.\"", "«Prendi la pallina più leggera che hai. Nel ruscello non si lancia con un tonfo, si posa.»"],["Der See dahinter", "The lake beyond", "Il lago oltre"],["Omas Karte · zweites Blatt", "Grandma's map · second sheet", "La mappa della nonna · secondo foglio"],["„Wo der Bach aus dem See läuft, wird er breit und langsam. Emil hat hier nie gefischt – zu wenig Strömung, hat er gesagt. Er hat sich geirrt.\"", "\"Where the brook leaves the lake it grows wide and slow. Emil never fished here – not enough current, he said. He was wrong.\"", "«Dove il ruscello esce dal lago diventa largo e lento. Emil non ha mai pescato qui – troppo poca corrente, diceva. Si sbagliava.»"],["„Im Herbst ziehen die Seeforellen in den Auslauf. Silbern, schwer und misstrauisch. Sie fressen, was der See ihnen bringt, also schau unter die Steine, bevor du anknotest.\"", "\"In autumn the lake trout run into the outflow. Silver, heavy and suspicious. They eat what the lake brings them, so look under the rocks before you tie on.\"", "«In autunno le trote lacustri entrano nell'emissario. Argentee, pesanti e diffidenti. Mangiano ciò che il lago porta loro, quindi guarda sotto i sassi prima di annodare.»"],["„Lass dir Zeit. In langsamem Wasser hat der Fisch alle Zeit der Welt, deine Nymphe anzuschauen.\"", "\"Take your time. In slow water the fish has all the time in the world to look at your nymph.\"", "«Prenditi tempo. Nell'acqua lenta il pesce ha tutto il tempo del mondo per guardare la tua ninfa.»"],["Unter gelbem Laub", "Under yellow leaves", "Sotto le foglie gialle"],["Deine Handschrift · Staffel 3", "Your handwriting · season 3", "La tua calligrafia · stagione 3"],["Lenis Karte endet am See. Den Rest schreibst du selbst. Im Oktober fährst du dorthin, wo die Smaragda breit wird und durch den Auwald schlingert.", "Leni's map ends at the lake. The rest you write yourself. In October you drive to where the Smaragda grows wide and winds through the floodplain forest.", "La mappa di Leni finisce al lago. Il resto lo scrivi tu. In ottobre vai dove la Smaragda si allarga e serpeggia nel bosco golenale."],["Das Wasser trägt Farbe vom Regen, die Blätter treiben, und am Grund stehen Barben wie graue Schatten nebeneinander. Hier unten zählt nicht die feine Imitation. Hier zählt, was man im Trüben noch sieht.", "The water carries colour from the rain, leaves drift, and on the bottom barbel stand side by side like grey shadows. Down here the fine imitation does not count. What counts is what can still be seen in the murk.", "L'acqua porta il colore della pioggia, le foglie derivano e sul fondo i barbi stanno fianco a fianco come ombre grigie. Quaggiù non conta l'imitazione fine. Conta ciò che si vede ancora nel torbido."],["Du schreibst dir auf: schwer fischen, auffällig fischen, und dem Vorfach nichts zumuten, was es nicht hält.", "You note down: fish heavy, fish bright, and ask nothing of the tippet that it cannot hold.", "Ti annoti: pescare pesante, pescare vistoso, e non chiedere al finale più di quanto regga."],["Das alte Wehr", "The old weir", "La vecchia briglia"],["Deine Handschrift · zweite Seite", "Your handwriting · second page", "La tua calligrafia · seconda pagina"],["Unterhalb des alten Wehrs kocht das Wasser. Der Müller ist lange fort, aber die Regenbogenforellen, die er einst besetzt hat, sind geblieben und groß geworden.", "Below the old weir the water boils. The miller is long gone, but the rainbow trout he once stocked have stayed and grown big.", "Sotto la vecchia briglia l'acqua ribolle. Il mugnaio se n'è andato da tempo, ma le trote iridee che aveva immesso sono rimaste e sono cresciute."],["Im weißen Wasser hat kein Fisch Zeit zum Überlegen. Was auffällt, wird genommen. Was zu leicht ist, kommt nie unten an.", "In white water no fish has time to think. What stands out gets taken. What is too light never reaches the bottom.", "Nell'acqua bianca nessun pesce ha tempo di pensare. Ciò che si nota viene preso. Ciò che è troppo leggero non arriva mai sul fondo."],["Ein alter Mann am Ufer sieht dir zu. „Wenn du die hier landest\", sagt er, „dann geh im Winter an die Mündung. Dort jagt einer, der Forellen frisst.\"", "An old man on the bank watches you. \"If you can land these,\" he says, \"go to the confluence in winter. Something hunts there that eats trout.\"", "Un vecchio sulla riva ti guarda. «Se riesci a prendere queste», dice, «d'inverno vai alla confluenza. Lì caccia uno che mangia le trote.»"],["Raureif", "Hoarfrost", "Brina"],["Deine Handschrift · Staffel 4", "Your handwriting · season 4", "La tua calligrafia · stagione 4"],["Im Januar ist der Fluss so klar, dass man die Kiesel zählen kann. Die Äschen stehen jetzt dicht beisammen im tiefen Zug und nehmen nur, was ihnen fast ins Maul treibt.", "In January the river is so clear you can count the pebbles. The grayling now hold close together in the deep run and take only what drifts almost into their mouths.", "A gennaio il fiume è così limpido che si possono contare i ciottoli. I temoli stanno fitti nella corrente profonda e prendono solo ciò che arriva quasi in bocca."],["Kalte Finger, dünnstes Vorfach, kleinste Bewegungen. Wer hier grob fischt, fischt allein.", "Cold fingers, the thinnest tippet, the smallest movements. Fish roughly here and you fish alone.", "Dita fredde, il finale più sottile, i movimenti più piccoli. Chi pesca in modo grossolano, qui pesca da solo."],["Opa hätte gesagt: „Im Winter lernt man, was man im Sommer nur geglaubt hat zu können.\"", "Grandpa would have said: \"In winter you learn what in summer you only thought you could do.\"", "Il nonno avrebbe detto: «D'inverno si impara ciò che d'estate si credeva soltanto di saper fare.»"],["Der Winterkönig", "The winter king", "Il re d'inverno"],["Deine Handschrift · letzte Seite", "Your handwriting · last page", "La tua calligrafia · ultima pagina"],["Wo die Smaragda in den großen Strom mündet, ist das Wasser tief und grün wie Flaschenglas. Hier jagt der Huchen – der Donaulachs, kupferrot, lang wie ein Ruder.", "Where the Smaragda joins the great river the water is deep and green as bottle glass. Here the huchen hunts – the Danube salmon, copper red, long as an oar.", "Dove la Smaragda sfocia nel grande fiume l'acqua è profonda e verde come vetro di bottiglia. Qui caccia l'huchen – il salmone del Danubio, rosso rame, lungo come un remo."],["Er steht am Rand des Kolks und wartet auf alles, was schwach wirkt. Eine kleine Nymphe sieht er nicht einmal an. Er will einen Happen, und er will ihn tief.", "He holds at the edge of the deep hole and waits for anything that looks weak. He does not even glance at a small nymph. He wants a mouthful, and he wants it deep.", "Sta al margine della buca e aspetta tutto ciò che sembra debole. Una ninfa piccola non la guarda nemmeno. Vuole un boccone, e lo vuole in profondità."],["Du knotest das stärkste Vorfach an, das du hast, und denkst an den Alten im Smaragdgumpen. Der hier ist größer.", "You tie on the strongest tippet you own and think of the Old One in the emerald pool. This one is bigger.", "Annodi il finale più robusto che hai e pensi al Vecchio della buca di smeraldo. Questo è più grande."],["Der ganze Fluss", "The whole river", "Tutto il fiume"],["Deine Handschrift", "Your handwriting", "La tua calligrafia"],["Über einen Meter. Der Huchen liegt im flachen Wasser, die Kiemen arbeiten, und du hältst ihn nur so lange, wie man einen Atemzug anhält.", "More than a metre. The huchen lies in the shallows, gills working, and you hold him only as long as one holds a breath.", "Più di un metro. L'huchen è nell'acqua bassa, le branchie lavorano, e lo tieni solo quanto si trattiene un respiro."],["Dann schiebt er sich mit einem Schlag der Schwanzflosse zurück in den Strom.", "Then, with one stroke of his tail, he pushes back into the current.", "Poi, con un colpo di coda, si spinge di nuovo nella corrente."],["Von der Quelle bis zur Mündung: Du hast die Smaragda einmal ganz gefischt. Du klappst das Tagebuch zu, legst Lenis Karte hinein und schreibst auf den Umschlag einen neuen Namen neben den von Opa. Deinen.", "From the source to the confluence: you have fished the whole Smaragda once. You close the diary, slip Leni's map inside and write a new name on the cover next to Grandpa's. Yours.", "Dalla sorgente alla confluenza: hai pescato tutta la Smaragda. Chiudi il diario, ci infili la mappa di Leni e sulla copertina scrivi un nuovo nome accanto a quello del nonno. Il tuo."],["Als du das Tagebuch zuklappst, löst sich hinten ein gefaltetes Blatt. Eine Karte – und eine Handschrift, die nicht Opas ist.", "As you close the diary, a folded sheet comes loose at the back. A map – and handwriting that is not Grandpa's.", "Quando chiudi il diario, dal fondo si stacca un foglio piegato. Una mappa – e una calligrafia che non è quella del nonno."],["Fange 3 Fische in Gumpen", "Catch 3 fish in pools", "Cattura 3 pesci nelle buche"],["Fange 2 verschiedene Arten", "Catch 2 different species", "Cattura 2 specie diverse"],["Lande 3 Fische in Folge, ohne einen zu verlieren", "Land 3 fish in a row without losing one", "Porta a guadino 3 pesci di fila senza perderne uno"],["Der Mühlbach", "The mill brook", "Il rio del mulino"],["Schmal und verwachsen", "Narrow and overgrown", "Stretto e coperto di rami"],["Der Mühlbach", "The mill brook", "Il rio del mulino"],["Opas Tagebuch · ein eingelegter Zettel", "Grandpa's diary · a loose note", "Il diario del nonno · un foglietto infilato"],["„Bevor du zu den Äschen gehst, nimm den Mühlbach mit. Er ist kaum breiter als meine Rute lang ist, und die Erlen hängen bis aufs Wasser.\"", "\"Before you go to the grayling, fish the mill brook. It is barely wider than my rod is long, and the alders hang down to the water.\"", "«Prima di andare dai temoli, fai il rio del mulino. È largo poco più della mia canna, e gli ontani pendono fin sull'acqua.»"],["„Hier lernst du, einen Fisch auch zu behalten. Wenig Platz, kurze Fluchten, und jeder Fehler hängt im Ast. Drei hintereinander, ohne einen zu verlieren – dann bist du so weit.\"", "\"Here you learn to keep a fish once it is on. Little room, short runs, and every mistake ends up in a branch. Three in a row without losing one – then you are ready.\"", "«Qui impari a non perdere un pesce allamato. Poco spazio, fughe corte, e ogni errore finisce su un ramo. Tre di fila senza perderne uno – allora sei pronto.»"],["Fange 4 Fische in der Rinne", "Catch 4 fish in the channel", "Cattura 4 pesci nel canale"],["Fange 3 Fische auf eine unauffällige Nymphe (Pheasant Tail, Walt's Worm, Peeping Caddis)", "Catch 3 fish on a drab nymph (Pheasant Tail, Walt's Worm, Peeping Caddis)", "Cattura 3 pesci con una ninfa discreta (Pheasant Tail, Walt's Worm, Peeping Caddis)"],["Fange zusammen 2 Meter Fisch", "Catch 2 metres of fish in total", "Cattura in totale 2 metri di pesce"],["Die Kiesbank", "The gravel bar", "Il ghiareto"],["Flach und klar", "Shallow and clear", "Basso e limpido"],["Die Kiesbank", "The gravel bar", "Il ghiareto"],["Opas Tagebuch · Randnotiz", "Grandpa's diary · note in the margin", "Il diario del nonno · nota a margine"],["„Auf der Kiesbank ist das Wasser knietief und klar wie Luft. Die Fische sehen dich lange, bevor du sie siehst. Bleib tief, wate langsam, und fisch die Rinne an – dort, wo der Grund dunkler wird.\"", "\"On the gravel bar the water is knee-deep and clear as air. The fish see you long before you see them. Stay low, wade slowly, and fish the channel – where the bottom turns darker.\"", "«Sul ghiareto l'acqua arriva al ginocchio ed è limpida come l'aria. I pesci ti vedono molto prima che tu veda loro. Stai basso, guada piano e pesca il canale – dove il fondo si fa più scuro.»"],["„Nichts Buntes. Hier fängt das Unscheinbare.\"", "\"Nothing flashy. Here the plain fly catches.\"", "«Niente di vistoso. Qui prende ciò che non si nota.»"],["Fange 3 Fische mit der 4-mm-Perle", "Catch 3 fish on the 4 mm bead", "Cattura 3 pesci con la pallina da 4 mm"],["Fange einen Bachsaibling ab 34 cm", "Catch a brook trout of 34 cm or more", "Cattura un salmerino di fonte di almeno 34 cm"],["Fange 2 Fische im Kissen vor einem Stein", "Catch 2 fish in the cushion in front of a rock", "Cattura 2 pesci nel cuscino davanti a un sasso"],["Der Wasserfallgumpen", "The waterfall pool", "La buca della cascata"],["Tief unterm Sturz", "Deep below the falls", "Profonda sotto il salto"],["Unterm Sturz", "Below the falls", "Sotto il salto"],["Omas Karte · am Rand notiert", "Grandma's map · noted in the margin", "La mappa della nonna · annotato a margine"],["„Zwischen Quelle und See fällt der Bach über eine Stufe. Darunter hat er sich ein Loch gegraben, so tief, dass man den Grund nicht sieht.\"", "\"Between the source and the lake the brook drops over a ledge. Below it has dug a hole so deep you cannot see the bottom.\"", "«Tra la sorgente e il lago il ruscello cade da un gradino. Sotto ha scavato una buca così profonda che non si vede il fondo.»"],["„Emil hätte gelacht: Leni mit der dicksten Perle. Aber anders kommst du hier nicht hinunter. Und vergiss die Steine nicht – die Fische stehen auch davor, im Kissen, wo das Wasser sich staut.\"", "\"Emil would have laughed: Leni with the fattest bead. But there is no other way down here. And do not forget the rocks – fish also hold in front of them, in the cushion where the water piles up.\"", "«Emil avrebbe riso: Leni con la pallina più grossa. Ma qui non si scende in altro modo. E non dimenticare i sassi – i pesci stanno anche davanti, nel cuscino dove l'acqua si accumula.»"],["Fange 5 Fische bei angetrübtem oder trübem Wasser", "Catch 5 fish in coloured or murky water", "Cattura 5 pesci con acqua velata o torbida"],["Fange 2 Fische im Morgennebel oder Abendlicht", "Catch 2 fish in morning mist or evening light", "Cattura 2 pesci nella nebbia del mattino o alla luce della sera"],["Fange eine Bachforelle ab 45 cm", "Catch a brown trout of 45 cm or more", "Cattura una trota fario di almeno 45 cm"],["Der Moorbach", "The moor brook", "Il ruscello di torbiera"],["Dunkles Wasser", "Dark water", "Acqua scura"],["Dunkles Wasser", "Dark water", "Acqua scura"],["Omas Karte · mit Tinte nachgetragen", "Grandma's map · added in ink", "La mappa della nonna · aggiunto a inchiostro"],["„Aus dem Moor kommt ein zweiter Bach, braun wie Tee. Die Leute sagen, da sei nichts drin. Die Leute fischen ihn mittags.\"", "\"A second brook comes out of the moor, brown as tea. People say there is nothing in it. People fish it at noon.\"", "«Dalla torbiera esce un secondo ruscello, bruno come il tè. La gente dice che dentro non c'è niente. La gente lo pesca a mezzogiorno.»"],["„Geh in der Dämmerung. Dann kommen die dunklen Forellen aus den Unterständen, und sie sind größer, als der Bach vermuten lässt. Steht die Sonne hoch, komm einfach ein andermal wieder.\"", "\"Go at dusk or dawn. Then the dark trout come out from under the banks, and they are bigger than the brook suggests. If the sun is high, simply come back another time.\"", "«Vai al crepuscolo. Allora le trote scure escono dai ripari, e sono più grosse di quanto il ruscello lasci pensare. Se il sole è alto, torna un'altra volta.»"],["Fange 4 Fische mit der leichten 2,5-mm-Perle", "Catch 4 fish on the light 2.5 mm bead", "Cattura 4 pesci con la pallina leggera da 2,5 mm"],["Fange zusammen 3 Meter Fisch", "Catch 3 metres of fish in total", "Cattura in totale 3 metri di pesce"],["Lande 4 Fische in Folge, ohne einen zu verlieren", "Land 4 fish in a row without losing one", "Porta a guadino 4 pesci di fila senza perderne uno"],["Der Altarm", "The oxbow", "La lanca"],["Stilles Wasser", "Still water", "Acqua ferma"],["Der Altarm", "The oxbow", "La lanca"],["Deine Handschrift · ein Nachmittag im Oktober", "Your handwriting · an October afternoon", "La tua calligrafia · un pomeriggio d'ottobre"],["Hinter dem Auwald liegt ein alter Arm des Flusses, fast ohne Strömung. Das Laub steht auf dem Wasser wie auf einem Teller.", "Behind the floodplain forest lies an old arm of the river, almost without current. The leaves sit on the water as on a plate.", "Dietro il bosco golenale c'è un vecchio braccio del fiume, quasi senza corrente. Le foglie stanno sull'acqua come su un piatto."],["Hier sinkt alles von selbst. Eine schwere Perle liegt nach zwei Sekunden im Schlamm. Du nimmst die leichteste, die du hast, und lernst, wie lange ein Drill dauert, wenn der Fisch alle Zeit der Welt hat.", "Here everything sinks by itself. A heavy bead lies in the mud after two seconds. You take the lightest you have and learn how long a fight lasts when the fish has all the time in the world.", "Qui tutto affonda da sé. Una pallina pesante è nel fango dopo due secondi. Prendi la più leggera che hai e impari quanto dura un combattimento quando il pesce ha tutto il tempo del mondo."],["Fange 3 Fische an der Strömungskante neben einem Stein", "Catch 3 fish on the seam beside a rock", "Cattura 3 pesci sulla linea di corrente accanto a un sasso"],["Fange 4 verschiedene Arten", "Catch 4 different species", "Cattura 4 specie diverse"],["Fange einen Fisch ab 54 cm", "Catch a fish of 54 cm or more", "Cattura un pesce di almeno 54 cm"],["Die Steinbrücke", "The stone bridge", "Il ponte di pietra"],["Zwischen den Pfeilern", "Between the piers", "Tra i piloni"],["Zwischen den Pfeilern", "Between the piers", "Tra i piloni"],["Deine Handschrift · unter der Brücke", "Your handwriting · under the bridge", "La tua calligrafia · sotto il ponte"],["Die alte Steinbrücke steht auf Blöcken, groß wie Autos. An jedem teilt sich das Wasser, und an jeder Kante, wo schnell auf langsam trifft, steht ein Fisch und lässt sich das Futter vorbeitragen.", "The old stone bridge stands on blocks as big as cars. At each one the water splits, and on every seam where fast meets slow a fish holds and lets the food drift by.", "Il vecchio ponte di pietra poggia su blocchi grossi come automobili. A ognuno l'acqua si divide, e su ogni linea dove il veloce incontra il lento un pesce sta fermo e lascia passare il cibo."],["Vier Arten in einem einzigen Zug, schreibst du abends auf. Opa hätte es nicht geglaubt.", "Four species in a single run, you write down that evening. Grandpa would not have believed it.", "Quattro specie in un solo tratto, scrivi la sera. Il nonno non ci avrebbe creduto."],["Fange 4 Fische mit der 4-mm-Perle", "Catch 4 fish on the 4 mm bead", "Cattura 4 pesci con la pallina da 4 mm"],["Fange 3 Fische in der Tasche hinter einem Stein", "Catch 3 fish in the pocket behind a rock", "Cattura 3 pesci nella tasca dietro un sasso"],["Fange einen Fisch ab 56 cm", "Catch a fish of 56 cm or more", "Cattura un pesce di almeno 56 cm"],["Die Eisrinne", "The ice chute", "La gola di ghiaccio"],["Eng, schnell, bitterkalt", "Narrow, fast, bitterly cold", "Stretta, veloce, gelida"],["Die Eisrinne", "The ice chute", "La gola di ghiaccio"],["Deine Handschrift · Februar", "Your handwriting · February", "La tua calligrafia · febbraio"],["Zwischen Winterzug und Mündung zwängt sich der Fluss durch eine Rinne, an deren Wänden das Eis in Vorhängen hängt. Die Sonne kommt hier im Februar nicht hin.", "Between the winter run and the confluence the river squeezes through a chute whose walls are hung with curtains of ice. In February the sun does not reach here.", "Tra la corrente d'inverno e la confluenza il fiume si stringe in una gola dalle cui pareti il ghiaccio pende a tende. A febbraio il sole qui non arriva."],["Das Wasser ist schnell, die Fische sind träge und stehen dort, wo sie am wenigsten arbeiten müssen: in den Taschen hinter den Blöcken. Schweres Tungsten, kurze Driften, und Finger, die du nach einer Stunde nicht mehr spürst.", "The water is fast, the fish are sluggish and hold where they have to work least: in the pockets behind the boulders. Heavy tungsten, short drifts, and fingers you cannot feel after an hour.", "L'acqua è veloce, i pesci sono pigri e stanno dove faticano meno: nelle tasche dietro i massi. Tungsteno pesante, derive corte, e dita che dopo un'ora non senti più."],["Fange 6 Fische im Nebel", "Catch 6 fish in the fog", "Cattura 6 pesci nella nebbia"],["Fange 3 Fische auf die passende Nymphe (vorher Stein umdrehen)", "Catch 3 fish on the matching nymph (turn a rock first)", "Cattura 3 pesci con la ninfa giusta (prima gira un sasso)"],["Fange zusammen 4 Meter Fisch", "Catch 4 metres of fish in total", "Cattura in totale 4 metri di pesce"],["Die Nebelstrecke", "The fog beat", "Il tratto della nebbia"],["Wo man den Sighter kaum sieht", "Where you can barely see the sighter", "Dove il sighter si vede appena"],["Im Nebel", "In the fog", "Nella nebbia"],["Deine Handschrift · der Morgen davor", "Your handwriting · the morning before", "La tua calligrafia · la mattina prima"],["Kurz vor der Mündung liegt jeden Wintermorgen Nebel auf dem Fluss, so dicht, dass das andere Ufer verschwindet. Der Sighter ist ein blasser Strich im Grau.", "Just above the confluence fog lies on the river every winter morning, so thick the far bank disappears. The sighter is a pale line in the grey.", "Poco prima della confluenza ogni mattina d'inverno la nebbia copre il fiume, così fitta che l'altra riva scompare. Il sighter è un tratto pallido nel grigio."],["Du fischst mehr mit der Hand als mit den Augen. Jedes Zögern in der Schnur könnte ein Biss sein. Wer das hier kann, ist bereit für den, der unten wartet.", "You fish more with your hand than with your eyes. Every hesitation in the line could be a take. If you can do this, you are ready for the one waiting below.", "Peschi più con la mano che con gli occhi. Ogni esitazione della lenza potrebbe essere un'abboccata. Se sai fare questo, sei pronto per quello che aspetta più giù."],["Grauer Körper, weißer Sichtflügel. Die eine Trockenfliege, die fast jede schlüpfende Eintagsfliege abdeckt.", "Grey body, white sighting post. The one dry fly that covers almost any hatching mayfly.", "Corpo grigio, ala bianca ben visibile. L'unica secca che copre quasi ogni effimera in schiusa."],["Flügel aus Hirschhaar, schwimmt wie ein Korken. Für Abende, an denen die Köcherfliegen über dem Wasser tanzen.", "Wing of elk hair, floats like a cork. For evenings when the caddis dance over the water.", "Ala di pelo d'alce, galleggia come un tappo. Per le sere in cui i tricotteri danzano sull'acqua."],["Der Körper hängt im Oberflächenfilm wie ein Insekt beim Schlüpfen. Für Fische, die knapp unter der Oberfläche fressen.", "The body hangs in the surface film like an insect hatching. For fish feeding just below the surface.", "Il corpo pende nel film superficiale come un insetto che schiude. Per i pesci che mangiano appena sotto la superficie."],["Groß, buschig, orange. Imitiert die erwachsene Steinfliege – ein Bissen, für den auch große Forellen hochkommen.", "Big, bushy, orange. Imitates the adult stonefly – a mouthful even big trout will rise for.", "Grande, folta, arancione. Imita la perla adulta – un boccone per cui salgono anche le trote grosse."],["Rot, Pfauengras, weiße Flügel. Imitiert nichts – und wird im schnellen Wasser trotzdem genommen, weil man sie einfach sieht.", "Red, peacock herl, white wings. Imitates nothing – and still gets taken in fast water because it is simply visible.", "Rosso, pavone, ali bianche. Non imita nulla – eppure in acqua veloce viene presa, perché semplicemente si vede."],["Euro-Nymphe", "Euro nymph", "Ninfa europea"],["Nymphenrute 10′ #3. Kurze Schnur, hohe Rute, direkter Kontakt über den Sighter. Am genauesten auf kurze Distanz, bis etwa 7 m.", "Nymph rod 10′ #3. Short line, high rod, direct contact through the sighter. Most precise at short range, up to about 7 m.", "Canna da ninfa 10′ #3. Lenza corta, canna alta, contatto diretto tramite il sighter. La più precisa a corta distanza, fino a circa 7 m."],["Indikator", "Indicator", "Indicatore"],["Allroundrute 9′6″ #4. Die Nymphe hängt unter einem schwimmenden Bissanzeiger. Würfe bis 10 m, lose Schnur schadet nicht – aber die Tiefe stellst du selbst ein, und der Indikator muss die Perle tragen können.", "All-round rod 9′6″ #4. The nymph hangs below a floating strike indicator. Casts up to 10 m, slack line does no harm – but you set the depth yourself, and the indicator has to carry the bead.", "Canna tuttofare 9′6″ #4. La ninfa pende sotto un segnalatore galleggiante. Lanci fino a 10 m, la lenza lenta non nuoce – ma la profondità la regoli tu, e l'indicatore deve reggere la pallina."],["Trockenfliege", "Dry fly", "Mosca secca"],["Trockenfliegenrute 9′ #4. Die Fliege treibt auf der Oberfläche. Nur steigende Fische nehmen sie – achte auf die Ringe im Wasser. Würfe bis 12 m. In der Fliegendose siehst du mit dieser Rute nur Trockenfliegen.", "Dry fly rod 9′ #4. The fly drifts on the surface. Only rising fish take it – watch for rings on the water. Casts up to 12 m. With this rod the fly box shows dry flies only.", "Canna da secca 9′ #4. La mosca deriva in superficie. La prendono solo i pesci che bollano – cerca i cerchi sull'acqua. Lanci fino a 12 m. Con questa canna la scatola mostra solo mosche secche."],["New-Zealand-Wolle", "New Zealand wool", "Lana neozelandese"],["Ein Büschel Schafwolle im Silikonschlauch. Landet wie eine Feder und zeigt jedes Zupfen – trägt aber nur leichte Nymphen.", "A tuft of sheep wool in silicone tubing. Lands like a feather and shows every pluck – but only carries light nymphs.", "Un ciuffo di lana di pecora nel tubetto di silicone. Si posa come una piuma e mostra ogni tocco – ma regge solo ninfe leggere."],["Palsa-Klebeschaum", "Palsa pinch-on foam", "Schiuma adesiva Palsa"],["Selbstklebender Schaumstreifen ums Vorfach. Winzig und unauffällig, trägt am wenigsten von allen.", "Self-adhesive foam strip pinched onto the leader. Tiny and unobtrusive, carries the least of all.", "Striscetta di schiuma adesiva sul finale. Minuscola e discreta, è quella che regge meno."],["Loon Biostrike (Knete)", "Loon Biostrike (putty)", "Loon Biostrike (pasta)"],["Schwimmende Knetmasse, die du in beliebiger Größe aufs Vorfach rollst. Empfindlich und leise, mittlere Tragkraft.", "Floating putty you roll onto the leader in any size. Sensitive and quiet, medium buoyancy.", "Pasta galleggiante che arrotoli sul finale nella misura voluta. Sensibile e silenziosa, portata media."],["Airlock", "Airlock", "Airlock"],["Schaumkörper mit Schraubmutter, schnell verstellbar. Solider Allrounder für mittlere Gewichte.", "Foam body with a screw nut, quick to adjust. A solid all-rounder for medium weights.", "Corpo in schiuma con dado a vite, rapido da regolare. Un tuttofare solido per pesi medi."],["Oros (Styroporkugel)", "Oros (foam ball)", "Oros (pallina di polistirolo)"],["Zweiteilige Styroporkugel zum Zusammenschrauben. Trägt auch schwere Perlen, setzt aber hörbar auf.", "Two-piece foam ball that screws together. Carries heavy beads too, but lands audibly.", "Pallina di polistirolo in due pezzi che si avvitano. Regge anche palline pesanti, ma si posa con rumore."],["Thingamabobber", "Thingamabobber", "Thingamabobber"],["Luftgefüllte Plastikkugel. Trägt alles und geht nie unter – klatscht aber aufs Wasser und zeigt feine Bisse schlecht.", "Air-filled plastic ball. Carries anything and never sinks – but slaps onto the water and shows subtle takes poorly.", "Pallina di plastica piena d'aria. Regge tutto e non affonda mai – ma schiaffeggia l'acqua e mostra male le abboccate delicate."],["Ein Fisch steigt! Steigende Fische nehmen nur die Trockenfliege – wechsle im Rig die Rute.", "A fish is rising! Rising fish only take a dry fly – switch rods in the rig.", "Un pesce bolla! I pesci che bollano prendono solo la secca – cambia canna nel rig."],["Der Indikator säuft ab – die Perle ist zu schwer für ihn. Nimm einen tragfähigeren oder eine leichtere Perle.", "The indicator is going under – the bead is too heavy for it. Use a more buoyant one or a lighter bead.", "L'indicatore affonda – la pallina è troppo pesante. Usane uno più portante o una pallina più leggera."],["Die Nymphe trieb zu hoch über dem Grund. Stell im Rig die Tiefe unter dem Indikator größer ein.", "The nymph drifted too high above the bottom. Set a greater depth below the indicator in the rig.", "La ninfa derivava troppo alta sul fondo. Aumenta nel rig la profondità sotto l'indicatore."],["Im Hutband stecken noch zwei Adams von Opa.", "Two of Grandpa's Adams are still stuck in the hat band.", "Nel nastro del cappello ci sono ancora due Adams del nonno."],["Trockenfliegen", "Dry flies", "Mosche secche"],["Nymphen", "Nymphs", "Ninfe"],["nichts Bestimmtes – eine Reizfliege", "nothing in particular – an attractor", "niente di preciso – una mosca di richiamo"],["Rute & Methode", "Rod & method", "Canna e tecnica"],["Indikator", "Indicator", "Indicatore"],["Aktuelle Last: {0}-mm-Perle an {1}.", "Current load: {0} mm bead on {1}.", "Carico attuale: pallina da {0} mm su {1}."],["trägt", "carries it", "regge"],["liegt tief", "rides low", "galleggia basso"],["säuft ab", "sinks", "affonda"],["Tragkraft", "Buoyancy", "Portata"],["Empfindlichkeit", "Sensitivity", "Sensibilità"],["Leises Aufsetzen", "Quiet landing", "Posa silenziosa"],["Montiert", "Fitted", "Montato"],["Montieren", "Fit", "Monta"],["Tiefe unter dem Indikator", "Depth below the indicator", "Profondità sotto l'indicatore"],["Faustregel: etwa so tief wie das Wasser an der Stelle. Zu kurz – die Nymphe treibt über die Fische hinweg. Zu lang – sie schleift am Grund und bleibt hängen. Die Wassertiefe zeigt dir die Anzeige oben rechts während der Drift.", "Rule of thumb: about as deep as the water at that spot. Too short – the nymph drifts over the fish. Too long – it drags on the bottom and snags. The gauge at the top right shows the water depth during the drift.", "Regola pratica: circa quanto è profonda l'acqua in quel punto. Troppo corto – la ninfa passa sopra i pesci. Troppo lungo – striscia sul fondo e si incaglia. L'indicatore in alto a destra mostra la profondità durante la deriva."],["Trockenfliege wählen", "Choose a dry fly", "Scegli una secca"],["Fliege, Perle und Vorfach wählen", "Choose fly, bead and tippet", "Scegli mosca, pallina e finale"],["Lautstärke", "Volume", "Volume"],["Eintagsfliegen", "Mayflies", "Effimere"],["Köcherfliegen", "Caddisflies", "Tricotteri"],["Steinfliegen", "Stoneflies", "Plecotteri"],["{0} (für die {1}; das häufigste Futter hier schlüpft nicht)", "{0} (for the {1}; the most common food here does not hatch)", "{0} (per {1}; il cibo più comune qui non schiude)"],["keine – dieses Futter lebt nur unter Wasser", "none – this food lives under water only", "nessuna – questo cibo vive solo sott'acqua"],["Passende Nymphen:", "Matching nymphs:", "Ninfe adatte:"],["Passende Trockenfliegen:", "Matching dry flies:", "Secche adatte:"],["Aus den Larven unter dem Stein schlüpfen die Fliegen über dem Wasser. Steigende Fische fressen genau diese – nimm die Trockenfliege zur selben Insektenart.", "The larvae under the rock hatch into the flies above the water. Rising fish eat exactly those – pick the dry fly for the same kind of insect.", "Dalle larve sotto il sasso schiudono le mosche sopra l'acqua. I pesci che bollano mangiano proprio quelle – scegli la secca dello stesso insetto."],["treibt frei", "drifting free", "deriva libera"],["furcht", "dragging", "draga"],["Rute", "rod", "canna"],["Die Schnur liegt über einem Stein und hält die Fliege fest – sie furcht. Rute heben und so werfen, dass kein Stein dazwischen liegt.", "The line is lying over a rock and holding the fly back – it is dragging. Lift the rod and cast so that no rock lies in between.", "La lenza è su un sasso e trattiene la mosca – draga. Alza la canna e lancia in modo che non ci sia un sasso in mezzo."]];
const IDX = { de: 0, en: 1, it: 2 }, MAP = new Map(D.map(r => [r[0], r]));
export const LANGS = [['de', 'Deutsch'], ['en', 'English'], ['it', 'Italiano']];
const KEY = 'nymphmaniac_lang';
let lang = 'de';
try { lang = localStorage.getItem(KEY) || (navigator.language || 'de').slice(0, 2).toLowerCase(); } catch (e) { /* */ }
if (!(lang in IDX)) lang = 'en';
export const getLang = () => lang;
export function setLang(l) { if (!(l in IDX)) return; lang = l; try { localStorage.setItem(KEY, l); } catch (e) { /* */ } document.documentElement.lang = l; }
export function T(s, ...a) {
  const r = MAP.get(s), o = r ? r[IDX[lang]] : s;
  return a.length ? o.replace(/\{(\d)\}/g, (m, i) => a[i]) : o;
}
// Felder eines Datenobjekts übersetzen; das deutsche Original bleibt unter _feld erhalten
export function loc(o, ...fields) {
  for (const f of fields) {
    if (o[f] == null) continue;
    const k = '_' + f; if (o[k] === undefined) o[k] = o[f];
    o[f] = Array.isArray(o[k]) ? o[k].map(x => T(x)) : T(o[k]);
  }
}
